generic_root_and_harness_sources.content:
param(
    [ValidateSet('xpact', 'xpact-core', 'xpact-baseline')]
    [string] $Implementation,
    [switch] $Assertions
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$RepoRoot = 'C:/Users/ander/Documents/xpact'
$ScratchRoot = Join-Path $RepoRoot 'build/parser-profile-20261025/core-files'
$Preparation = Get-Content -LiteralPath "$ScratchRoot/preparation.json" -Raw -Encoding UTF8 | ConvertFrom-Json
. "$RepoRoot/scripts/import_msvc_environment.ps1"
$Selected = if ($Implementation) { @($Implementation) } else { @('xpact', 'xpact-core') }
New-Item -ItemType Directory -Force -Path "$ScratchRoot/logs" | Out-Null

foreach ($Engine in $Selected) {
    $Info = $Preparation.engines.$Engine
    $env:ISE_EIFFEL = $Info.toolchain.ise_eiffel
    $env:ISE_LIBRARY = $Info.toolchain.ise_library
    $env:ISE_C_COMPILER = $Info.toolchain.ise_c_compiler
    if ($Engine -eq 'xpact-core') {
        foreach ($Property in $Info.source.environment.PSObject.Properties) {
            Set-Item -LiteralPath "Env:$($Property.Name)" -Value $Property.Value
        }
        $HelperHash = (Get-FileHash -LiteralPath $Info.native_helper.object -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($HelperHash -ne $Info.native_helper.object_sha256) { throw 'Pinned native helper object changed.' }
    }
    $Config = "$ScratchRoot/$Engine.ecf"
    if ((Get-FileHash -LiteralPath $Config -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Info.scratch_config_sha256) {
        throw "Prepared configuration changed: $Config"
    }
    $Mode = if ($Assertions) { 'FinalizedAssertions' } else { 'Finalized' }
    $Target = if ($Assertions) { 'catalog_assertions' } else { 'catalog' }
    $Project = "$ScratchRoot/projects/$Engine/$Mode"
    if (Test-Path -LiteralPath $Project) { throw "Use a fresh project directory: $Project" }
    New-Item -ItemType Directory -Path $Project -Force | Out-Null
    $CompilerArguments = @('-batch', '-clean', '-finalize')
    if ($Assertions) { $CompilerArguments += '-keep' }
    $CompilerArguments += @('-config', $Config, '-target', $Target, '-project_path', $Project)
    $Compiler = $Info.toolchain.eiffel_compiler
    $BeforeInputs = @{}
    $InputFiles = @(
        Get-ChildItem -LiteralPath "$ScratchRoot/root" -Filter '*.e' -File
        Get-ChildItem -LiteralPath "$RepoRoot/benchmarks/dual_catalog/shared" -Filter '*.e' -File
        Get-ChildItem -LiteralPath $Info.adapter_dir -Filter '*.e' -File
    )
    if ($Info.parser_source_dir) { $InputFiles += @(Get-ChildItem -LiteralPath $Info.parser_source_dir -Filter '*.e' -File) }
    foreach ($InputFile in $InputFiles) {
        $BeforeInputs[$InputFile.FullName] = (Get-FileHash -LiteralPath $InputFile.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
    }
    & $Compiler @CompilerArguments *> "$ScratchRoot/logs/$Engine-$Mode-eiffel.log"
    if ($LASTEXITCODE -ne 0) {
        Get-Content -LiteralPath "$ScratchRoot/logs/$Engine-$Mode-eiffel.log" -Tail 40
        throw "Eiffel generation failed: $Engine/$Mode"
    }
    $CodeDirectory = "$Project/EIFGENs/$Target/F_code"
    Push-Location $CodeDirectory
    try {
        & finish_freezing *> "$ScratchRoot/logs/$Engine-$Mode-c.log"
        if ($LASTEXITCODE -ne 0) {
            Get-Content -LiteralPath "$ScratchRoot/logs/$Engine-$Mode-c.log" -Tail 40
            throw "C compilation failed: $Engine/$Mode"
        }
    } finally { Pop-Location }
    foreach ($InputPath in $BeforeInputs.Keys) {
        if ((Get-FileHash -LiteralPath $InputPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $BeforeInputs[$InputPath]) {
            throw "Source changed during compilation: $InputPath"
        }
    }
    $Executable = Join-Path $CodeDirectory $Info.executable_name
    $Manifest = [ordered]@{
        status = 'built-not-qualified'
        implementation = $Engine
        assertions = [bool] $Assertions
        configuration = $Config
        configuration_sha256 = $Info.scratch_config_sha256
        compiler = $Compiler
        compiler_arguments = $CompilerArguments
        source_inputs = $BeforeInputs
        source_campaign_manifest = $Info.original_benchmark_manifest
        pinned_source = if ($Engine -eq 'xpact-core') { $Info.source } else { $null }
        parser_source_dir = $Info.parser_source_dir
        source_note = $Info.note
        native_helper = $Info.native_helper
        executable = $Executable
        executable_sha256 = (Get-FileHash -LiteralPath $Executable -Algorithm SHA256).Hash.ToLowerInvariant()
        makefile_sha256 = (Get-FileHash -LiteralPath "$CodeDirectory/Makefile" -Algorithm SHA256).Hash.ToLowerInvariant()
    }
    $Manifest | ConvertTo-Json -Depth 30 | Set-Content -LiteralPath "$ScratchRoot/$Engine-$Mode-build.json" -Encoding UTF8
    Write-Host $Executable
}
